167: 			}
168: 		case appmodulev2.HasGenesis:
169: 			m.logger.Debug("running initialization for module", "module", moduleName)
170: 			if err := module.InitGenesis(ctx, genesisData[moduleName]); err != nil {
171: 				return fmt.Errorf("init module %s: %w", moduleName, err)
172: 			}
173: 		case appmodulev2.HasABCIGenesis:
174: 			m.logger.Debug("running initialization for module", "module", moduleName)
